CREATE TABLE `agentes_publicos` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `nome` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nome_social` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cpf` char(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Somente digitos',
  `data_nascimento` date DEFAULT NULL,
  `email_institucional` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Sempre em minusculas',
  `email_alternativo` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `telefone` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Somente digitos, com DDD',
  `matricula` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Texto: preserva zeros a esquerda',
  `tipo_vinculo` enum('EFETIVO','COMISSIONADO','EMPREGADO_PUBLICO','ESTAGIARIO','RESIDENTE_TECNICO','TERCEIRIZADO','CEDIDO','COLABORADOR','OUTRO') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OUTRO',
  `cargo_id` smallint unsigned DEFAULT NULL,
  `funcao` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Funcao exercida (texto livre), ex.: Coordenador',
  `lotacao_id` smallint unsigned NOT NULL COMMENT 'Unidade Administrativa de lotacao',
  `data_ingresso` date DEFAULT NULL,
  `data_desligamento` date DEFAULT NULL,
  `situacao` enum('ATIVO','AFASTADO','DESLIGADO','OUTRO') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ATIVO',
  `observacoes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `criado_por` int unsigned DEFAULT NULL,
  `atualizado_por` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_agentes_cpf` (`cpf`),
  UNIQUE KEY `uq_agentes_matricula` (`matricula`),
  UNIQUE KEY `uq_agentes_email` (`email_institucional`),
  KEY `ix_agentes_nome` (`nome`),
  KEY `ix_agentes_lotacao` (`lotacao_id`),
  KEY `ix_agentes_cargo` (`cargo_id`),
  KEY `ix_agentes_vinculo` (`tipo_vinculo`),
  KEY `ix_agentes_situacao` (`situacao`),
  KEY `fk_agentes_criado_por` (`criado_por`),
  KEY `fk_agentes_atualizado_por` (`atualizado_por`),
  CONSTRAINT `fk_agentes_atualizado_por` FOREIGN KEY (`atualizado_por`) REFERENCES `usuarios` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_agentes_cargo` FOREIGN KEY (`cargo_id`) REFERENCES `cargos` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_agentes_criado_por` FOREIGN KEY (`criado_por`) REFERENCES `usuarios` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_agentes_lotacao` FOREIGN KEY (`lotacao_id`) REFERENCES `lotacoes` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_agentes_datas` CHECK (((`data_desligamento` is null) or (`data_ingresso` is null) or (`data_desligamento` >= `data_ingresso`)))
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
