--
-- Table structure for table `bloqueios_judiciais`
--

DROP TABLE IF EXISTS `bloqueios_judiciais`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bloqueios_judiciais` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `processo_judicial_id` int unsigned NOT NULL,
  `tipo` enum('BLOQUEIO','DESBLOQUEIO') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `data_lancamento` date NOT NULL COMMENT 'Data do bloqueio ou do desbloqueio',
  `valor` decimal(15,2) NOT NULL,
  `identificador` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Protocolo SISBAJUD, ordem ou conta',
  `observacao` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `criado_por` int unsigned DEFAULT NULL,
  `atualizado_por` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_bj_processo_data` (`processo_judicial_id`,`data_lancamento`),
  KEY `ix_bj_data` (`data_lancamento`),
  KEY `ix_bj_criado_por` (`criado_por`),
  KEY `fk_bj_atualizado_por` (`atualizado_por`),
  CONSTRAINT `fk_bj_atualizado_por` FOREIGN KEY (`atualizado_por`) REFERENCES `usuarios` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_bj_criado_por` FOREIGN KEY (`criado_por`) REFERENCES `usuarios` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_bj_processo_judicial` FOREIGN KEY (`processo_judicial_id`) REFERENCES `processos_judiciais` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_bj_valor` CHECK ((`valor` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

