CREATE TABLE `processo_administrativo_prioridades` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `processo_administrativo_id` int unsigned NOT NULL,
  `prioridade_id` smallint unsigned NOT NULL,
  `observacao` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `criado_por` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_papr_par` (`processo_administrativo_id`,`prioridade_id`),
  KEY `ix_papr_prioridade` (`prioridade_id`),
  KEY `fk_papr_criado_por` (`criado_por`),
  CONSTRAINT `fk_papr_criado_por` FOREIGN KEY (`criado_por`) REFERENCES `usuarios` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_papr_prioridade` FOREIGN KEY (`prioridade_id`) REFERENCES `prioridades` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_papr_processo` FOREIGN KEY (`processo_administrativo_id`) REFERENCES `processos_administrativos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
