-- Dumping data for table `processo_administrativo_solicitacoes`
--

LOCK TABLES `processo_administrativo_solicitacoes` WRITE;
/*!40000 ALTER TABLE `processo_administrativo_solicitacoes` DISABLE KEYS */;
/*!40000 ALTER TABLE `processo_administrativo_solicitacoes` ENABLE KEYS */;
