--
-- Table structure for table `processo_judicial_documentos`
--

DROP TABLE IF EXISTS `processo_judicial_documentos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `processo_judicial_documentos` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `processo_judicial_id` int unsigned NOT NULL,
  `movimentacao_id` int unsigned DEFAULT NULL,
  `documento_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Numero do documento no PJe, ex.: 249562011',
  `tipo` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Especie, ex.: Sentenca',
  `classificacao` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SENTENCA | DECISAO | ACORDAO | DESPACHO | EMBARGOS; NULL = nao decisoria',
  `data_documento` date DEFAULT NULL COMMENT 'Data do evento que juntou o documento',
  `hora` time DEFAULT NULL,
  `juntado_por` varchar(180) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `data_juntada` datetime DEFAULT NULL,
  `texto_integral` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `metodo_extracao` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'IFRAME_HTML | FETCH_HTML | PDF_SEM_TEXTO | NAO_LOCALIZADO | FALHA',
  `integra_extraida_em` datetime DEFAULT NULL,
  `ordem` smallint unsigned NOT NULL DEFAULT '0' COMMENT '0 = mais recente',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pjd_documento` (`processo_judicial_id`,`documento_id`),
  KEY `ix_pjd_classificacao` (`classificacao`),
  KEY `ix_pjd_movimentacao` (`movimentacao_id`),
  CONSTRAINT `fk_pjd_movimentacao` FOREIGN KEY (`movimentacao_id`) REFERENCES `processo_judicial_movimentacoes` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_pjd_processo_judicial` FOREIGN KEY (`processo_judicial_id`) REFERENCES `processos_judiciais` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3008 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

