CREATE TABLE `processos_administrativos` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `protocolo` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Ex.: SEPLAG-PRO-2026/16696',
  `data_abertura` date DEFAULT NULL,
  `objeto` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `procedimento` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Legado: texto livre anterior ao catalogo (procedimento_id). Preservado, nao editado',
  `procedimento_id` smallint unsigned DEFAULT NULL COMMENT 'Procedimento do catalogo',
  `origem` enum('MANUAL','SIGADOC') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL',
  `url_origem` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `extrator_versao` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `data_extracao` datetime DEFAULT NULL,
  `situacao` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'AGUARDANDO_ANDAMENTO | SOBRESTADO | ARQUIVADO | EM_TRANSITO | OUTRA',
  `situacao_descricao` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Rotulo oficial do SIGADOC, ex.: Arquivo Corrente',
  `responsavel_nome` varchar(180) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Agente publico com o processo',
  `responsavel_matricula` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `responsavel_lotacao` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Sigla da lotacao',
  `responsavel_lotacao_nome` varchar(180) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `prazo` date DEFAULT NULL COMMENT 'Prazo proprio; padrao: abertura + 30 dias',
  `prazo_hora` time DEFAULT NULL COMMENT 'NULL = ate o fim do dia',
  `prazo_vigente` date DEFAULT NULL COMMENT 'Calculado: o mais proximo entre o prazo proprio e o das acoes nao finalizadas',
  `prazo_vigente_hora` time DEFAULT NULL,
  `ativo` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Calculado: 1 = ha acao nao finalizada',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pa_protocolo` (`protocolo`),
  KEY `ix_pa_data_abertura` (`data_abertura`),
  KEY `ix_pa_created_at` (`created_at`),
  KEY `ix_pa_situacao` (`situacao`),
  KEY `ix_pa_procedimento` (`procedimento`),
  KEY `ix_pa_prazo_vigente` (`prazo_vigente`,`prazo_vigente_hora`),
  KEY `ix_pa_ativo` (`ativo`),
  KEY `ix_pa_procedimento_id` (`procedimento_id`),
  CONSTRAINT `fk_pa_procedimento` FOREIGN KEY (`procedimento_id`) REFERENCES `procedimentos` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=270 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `processos_administrativos`
--

LOCK TABLES `processos_administrativos` WRITE;
/*!40000 ALTER TABLE `processos_administrativos` DISABLE KEYS */;
