--
-- Table structure for table `processos_judiciais`
--

DROP TABLE IF EXISTS `processos_judiciais`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `processos_judiciais` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `numero_cnj` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Ex.: 1008695-17.2026.8.11.0006',
  `tribunal` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `orgao_julgador` varchar(180) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cargo_judicial` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Ex.: Juiz Titular',
  `competencia` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Competencia do orgao julgador',
  `jurisdicao` varchar(180) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `classe_judicial` varchar(180) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `classe_codigo` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Codigo CNJ da classe, ex.: 156',
  `classe_abreviada` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Sigla da classe no cabecalho do PJe, ex.: ProceComCiv',
  `assunto_principal` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `resumo_partes` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Resumo "Polo ativo X Polo passivo" do cabecalho',
  `data_autuacao` date DEFAULT NULL COMMENT 'Autuacao original (distinta da ultima distribuicao)',
  `data_distribuicao` date DEFAULT NULL,
  `valor_causa` decimal(15,2) DEFAULT NULL,
  `situacao` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `segredo_justica` tinyint(1) DEFAULT NULL COMMENT 'NULL = informacao nao disponivel',
  `justica_gratuita` tinyint(1) DEFAULT NULL COMMENT 'NULL = informacao nao disponivel',
  `tutela_liminar` tinyint(1) DEFAULT NULL COMMENT 'NULL = informacao nao disponivel',
  `prioridade` tinyint(1) DEFAULT NULL COMMENT 'NULL = informacao nao disponivel',
  `prioridade_descricao` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Motivo da prioridade, ex.: Idoso',
  `resumo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `observacoes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `origem` enum('MANUAL','PJE') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL',
  `url_origem` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `extrator_versao` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `data_extracao` datetime DEFAULT NULL,
  `data_ultima_atualizacao` date DEFAULT NULL COMMENT 'Ultima atualizacao informada pela fonte',
  `historico_completo` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = a cronologia importada cobre todo o processo; 0 = parcial (timeline paginada)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pj_numero_cnj` (`numero_cnj`),
  KEY `ix_pj_tribunal` (`tribunal`),
  KEY `ix_pj_situacao` (`situacao`),
  KEY `ix_pj_data_distribuicao` (`data_distribuicao`),
  KEY `ix_pj_created_at` (`created_at`),
  KEY `ix_pj_data_autuacao` (`data_autuacao`)
) ENGINE=InnoDB AUTO_INCREMENT=150 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

