-- Table structure for table `recurso_categorias`
--

DROP TABLE IF EXISTS `recurso_categorias`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `recurso_categorias` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `recurso_id` int unsigned NOT NULL,
  `categoria_id` smallint unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_recurso_categorias` (`recurso_id`,`categoria_id`),
  KEY `ix_recurso_categorias_categoria` (`categoria_id`),
  CONSTRAINT `fk_rc_categoria` FOREIGN KEY (`categoria_id`) REFERENCES `categorias_recurso` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_rc_recurso` FOREIGN KEY (`recurso_id`) REFERENCES `recursos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
